import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Sequence, Union

from azure.identity import ClientSecretCredential
from azure.monitor.query import MetricAggregationType, MetricsQueryClient


def query_metrics_by_resource_labels(
    resource_id: str,
    metric_names: Union[str, Sequence[str]],
    *,
    subscription_id: Optional[str] = None,
    resource_group: Optional[str] = None,
    resource_name: Optional[str] = None,
    namespace: Optional[str] = None,
    timespan_hours: int = 1,
    aggregation: Optional[Sequence[str]] = None,
) -> List[Dict[str, Any]]:
    """
    Query Azure Monitor Metrics for a resource, optionally filtering by resource labels/dimensions
    via the requested resource scope and metric namespace.

    Environment variables:
        AZURE_TENANT_ID
        AZURE_CLIENT_ID
        AZURE_CLIENT_SECRET
        AZURE_SUBSCRIPTION_ID (optional fallback for subscription_id)
    """
    tenant_id = os.environ["AZURE_TENANT_ID"]
    client_id = os.environ["AZURE_CLIENT_ID"]
    client_secret = os.environ["AZURE_CLIENT_SECRET"]
    subscription_id = subscription_id or os.environ.get("AZURE_SUBSCRIPTION_ID")

    if not subscription_id:
        raise ValueError("subscription_id is required (or set AZURE_SUBSCRIPTION_ID).")

    if isinstance(metric_names, str):
        metric_names = [metric_names]
    if not metric_names:
        raise ValueError("metric_names must not be empty.")

    cred = ClientSecretCredential(tenant_id=tenant_id, client_id=client_id, client_secret=client_secret)
    client = MetricsQueryClient(cred)

    start_time = datetime.now(timezone.utc) - timedelta(hours=timespan_hours)
    end_time = datetime.now(timezone.utc)

    agg_types = []
    for agg in (aggregation or ["Average"]):
        normalized = agg.strip().lower()
        if normalized == "average":
            agg_types.append(MetricAggregationType.AVERAGE)
        elif normalized == "minimum":
            agg_types.append(MetricAggregationType.MINIMUM)
        elif normalized == "maximum":
            agg_types.append(MetricAggregationType.MAXIMUM)
        elif normalized == "total":
            agg_types.append(MetricAggregationType.TOTAL)
        elif normalized == "count":
            agg_types.append(MetricAggregationType.COUNT)
        else:
            raise ValueError(f"Unsupported aggregation: {agg}")

    metrics = client.query_resource(
        resource_uri=resource_id,
        metric_names=list(metric_names),
        timespan=(start_time, end_time),
        aggregations=agg_types,
        metric_namespace=namespace,
    )

    results: List[Dict[str, Any]] = []
    for metric in metrics.metrics:
        for ts in metric.timeseries:
            metadata = {}
            if ts.metadata_values:
                metadata = {mv.name.value: mv.value for mv in ts.metadata_values}

            if resource_group and metadata.get("resourceGroup") and metadata["resourceGroup"] != resource_group:
                continue
            if resource_name and metadata.get("resourceName") and metadata["resourceName"] != resource_name:
                continue

            datapoints = []
            for point in ts.data:
                item: Dict[str, Any] = {"timestamp": point.timestamp.isoformat()}
                if point.average is not None:
                    item["average"] = point.average
                if point.minimum is not None:
                    item["minimum"] = point.minimum
                if point.maximum is not None:
                    item["maximum"] = point.maximum
                if point.total is not None:
                    item["total"] = point.total
                if point.count is not None:
                    item["count"] = point.count
                datapoints.append(item)

            results.append(
                {
                    "metric_name": metric.name.value if metric.name else None,
                    "namespace": metric.namespace,
                    "unit": getattr(metric.unit, "value", str(metric.unit)),
                    "timeseries_metadata": metadata,
                    "data": datapoints,
                }
            )

    return results
